using System.IO;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// The Steam download leaves the Linux server binary without the execute bit.
var path = Path.Combine((string)ThisService.RootDirectory, "ArmaReforgerServer");
if (File.Exists(path))
{
    var mode = File.GetUnixFileMode(path);
    var wanted = mode | UnixFileMode.UserExecute | UnixFileMode.GroupExecute;
    if (mode != wanted)
    {
        File.SetUnixFileMode(path, wanted);
        ScriptConsole.WriteLine((object)"Made ArmaReforgerServer executable.");
    }
}
